/**
 * SmartPOS Retail — PostgreSQL logical baseline v1.0 (POS-012).
 * Source: docs/DATABASE_SCHEMA.md, docs/BUSINESS_RULES.md, docs/OFFLINE_SYNC_DESIGN.md.
 *
 * This is a SCHEMA ONLY. Never import DB credentials into Electron.
 * BIGINT currency uses bigint mode, never JavaScript float/number for money.
 * UUIDs for sale/event are generated by the sending client, not the database.
 */
import { sql } from 'drizzle-orm';
import {
  bigint, boolean, check, foreignKey, index, integer, jsonb, pgTable,
  primaryKey, text, timestamp, unique, uniqueIndex, uuid,
} from 'drizzle-orm/pg-core';

const nowUtc = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const money = (name: string) => bigint(name, { mode: 'bigint' }).notNull();

export const stores = pgTable('stores', {
  id: uuid('id').primaryKey(),
  name: text('name').notNull(),
  timezone: text('timezone').notNull().default('Asia/Ho_Chi_Minh'),
  createdAt: nowUtc(),
});

export const users = pgTable('users', {
  id: uuid('id').primaryKey(),
  email: text('email').notNull(),
  passwordHash: text('password_hash').notNull(),
  active: boolean('active').notNull().default(true),
}, (t) => [
  unique('users_email_unique').on(t.email),
]);

export const storeMemberships = pgTable('store_memberships', {
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'restrict' }),
  role: text('role').notNull(),
  active: boolean('active').notNull().default(true),
}, (t) => [
  primaryKey({ columns: [t.storeId, t.userId], name: 'store_memberships_pk' }),
  check('store_memberships_role_not_empty', sql`length(trim(${t.role})) > 0`),
]);

export const devices = pgTable('devices', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  name: text('name').notNull(),
  offlineCheckoutEnabled: boolean('offline_checkout_enabled').notNull().default(false),
  revokedAt: timestamp('revoked_at', { withTimezone: true }),
}, (t) => [
  unique('devices_store_id_id_unique').on(t.storeId, t.id),
  uniqueIndex('devices_one_active_offline_pos_per_store')
    .on(t.storeId)
    .where(sql`${t.offlineCheckoutEnabled} = true AND ${t.revokedAt} IS NULL`),
]);

export const categories = pgTable('categories', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  name: text('name').notNull(),
}, (t) => [
  unique('categories_store_id_id_unique').on(t.storeId, t.id),
]);

export const brands = pgTable('brands', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  name: text('name').notNull(),
}, (t) => [
  unique('brands_store_id_id_unique').on(t.storeId, t.id),
]);

export const products = pgTable('products', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  categoryId: uuid('category_id').notNull(),
  brandId: uuid('brand_id').notNull(),
  name: text('name').notNull(),
  active: boolean('active').notNull().default(true),
}, (t) => [
  unique('products_store_id_id_unique').on(t.storeId, t.id),
  foreignKey({ columns: [t.storeId, t.categoryId], foreignColumns: [categories.storeId, categories.id], name: 'products_category_same_store_fk' }).onDelete('restrict'),
  foreignKey({ columns: [t.storeId, t.brandId], foreignColumns: [brands.storeId, brands.id], name: 'products_brand_same_store_fk' }).onDelete('restrict'),
]);

export const productVariants = pgTable('product_variants', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  productId: uuid('product_id').notNull(),
  sku: text('sku').notNull(),
  attributes: jsonb('attributes').notNull(),
  attributesKey: text('attributes_key').notNull(),
  priceVnd: money('price_vnd'),
  revision: bigint('revision', { mode: 'bigint' }).notNull().default(0n),
  active: boolean('active').notNull().default(true),
}, (t) => [
  unique('variants_store_id_id_unique').on(t.storeId, t.id),
  unique('variants_store_sku_unique').on(t.storeId, t.sku),
  unique('variants_product_attributes_unique').on(t.productId, t.attributesKey),
  foreignKey({ columns: [t.storeId, t.productId], foreignColumns: [products.storeId, products.id], name: 'variants_product_same_store_fk' }).onDelete('restrict'),
  check('variants_price_nonnegative', sql`${t.priceVnd} >= 0`),
  check('variants_revision_nonnegative', sql`${t.revision} >= 0`),
]);

export const inventoryBalances = pgTable('inventory_balances', {
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  variantId: uuid('variant_id').notNull(),
  qty: bigint('qty', { mode: 'bigint' }).notNull(),
  revision: bigint('revision', { mode: 'bigint' }).notNull().default(0n),
}, (t) => [
  primaryKey({ columns: [t.storeId, t.variantId], name: 'inventory_balances_pk' }),
  foreignKey({ columns: [t.storeId, t.variantId], foreignColumns: [productVariants.storeId, productVariants.id], name: 'balances_variant_same_store_fk' }).onDelete('restrict'),
  check('balances_revision_nonnegative', sql`${t.revision} >= 0`),
  // Signed qty is intentional: exceptional post-offline reconciliation can go negative.
]);

export const sales = pgTable('sales', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  deviceId: uuid('device_id').notNull(),
  cashierId: uuid('cashier_id').notNull(),
  clientCreatedAt: timestamp('client_created_at', { withTimezone: true }).notNull(),
  serverReceivedAt: timestamp('server_received_at', { withTimezone: true }).notNull().defaultNow(),
  totalVnd: money('total_vnd'),
  status: text('status').notNull(),
}, (t) => [
  unique('sales_store_id_id_unique').on(t.storeId, t.id),
  foreignKey({ columns: [t.storeId, t.deviceId], foreignColumns: [devices.storeId, devices.id], name: 'sales_device_same_store_fk' }).onDelete('restrict'),
  foreignKey({ columns: [t.storeId, t.cashierId], foreignColumns: [storeMemberships.storeId, storeMemberships.userId], name: 'sales_cashier_membership_fk' }).onDelete('restrict'),
  index('sales_store_client_created_idx').on(t.storeId, t.clientCreatedAt),
  check('sales_total_nonnegative', sql`${t.totalVnd} >= 0`),
  check('sales_status_not_empty', sql`length(trim(${t.status})) > 0`),
]);

export const inventoryMovements = pgTable('inventory_movements', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  variantId: uuid('variant_id').notNull(),
  saleId: uuid('sale_id').references(() => sales.id, { onDelete: 'restrict' }),
  qtyDelta: bigint('qty_delta', { mode: 'bigint' }).notNull(),
  kind: text('kind').notNull(),
  createdAt: nowUtc(),
}, (t) => [
  foreignKey({ columns: [t.storeId, t.variantId], foreignColumns: [productVariants.storeId, productVariants.id], name: 'movements_variant_same_store_fk' }).onDelete('restrict'),
  index('movements_variant_created_idx').on(t.variantId, t.createdAt),
  uniqueIndex('movements_sale_variant_kind_unique')
    .on(t.saleId, t.variantId, t.kind)
    .where(sql`${t.saleId} IS NOT NULL`),
  check('movements_kind_not_empty', sql`length(trim(${t.kind})) > 0`),
]);

export const saleItems = pgTable('sale_items', {
  id: uuid('id').primaryKey(),
  saleId: uuid('sale_id').notNull().references(() => sales.id, { onDelete: 'restrict' }),
  variantId: uuid('variant_id').notNull().references(() => productVariants.id, { onDelete: 'restrict' }),
  skuSnapshot: text('sku_snapshot').notNull(),
  nameSnapshot: text('name_snapshot').notNull(),
  attributesSnapshot: jsonb('attributes_snapshot').notNull(),
  quantity: integer('quantity').notNull(),
  unitPriceVnd: money('unit_price_vnd'),
  discountVnd: money('discount_vnd'),
  lineTotalVnd: money('line_total_vnd'),
}, (t) => [
  unique('sale_items_sale_id_id_unique').on(t.saleId, t.id),
  check('sale_items_quantity_positive', sql`${t.quantity} > 0`),
  check('sale_items_amounts_nonnegative', sql`${t.unitPriceVnd} >= 0 AND ${t.discountVnd} >= 0 AND ${t.lineTotalVnd} >= 0`),
  check('sale_items_line_total_consistent', sql`${t.lineTotalVnd}::numeric = ${t.quantity}::numeric * ${t.unitPriceVnd}::numeric - ${t.discountVnd}::numeric`),
  check('sale_items_snapshots_not_empty', sql`length(trim(${t.skuSnapshot})) > 0 AND length(trim(${t.nameSnapshot})) > 0`),
]);

export const payments = pgTable('payments', {
  id: uuid('id').primaryKey(),
  saleId: uuid('sale_id').notNull().references(() => sales.id, { onDelete: 'restrict' }),
  method: text('method').notNull(),
  dueVnd: money('due_vnd'),
  tenderedVnd: money('tendered_vnd'),
  changeVnd: money('change_vnd'),
}, (t) => [
  unique('payments_one_per_sale_unique').on(t.saleId),
  check('payments_cash_only', sql`${t.method} = 'CASH'`),
  check('payments_cash_amounts_valid', sql`${t.dueVnd} >= 0 AND ${t.tenderedVnd} >= ${t.dueVnd} AND ${t.changeVnd} = ${t.tenderedVnd} - ${t.dueVnd}`),
]);

export const syncReceipts = pgTable('sync_receipts', {
  eventId: uuid('event_id').notNull(),
  deviceId: uuid('device_id').notNull().references(() => devices.id, { onDelete: 'restrict' }),
  saleId: uuid('sale_id').notNull().references(() => sales.id, { onDelete: 'restrict' }),
  payloadHash: text('payload_hash').notNull(),
  resultCode: text('result_code').notNull(),
  ackJson: jsonb('ack_json').notNull(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  primaryKey({ columns: [t.deviceId, t.eventId], name: 'sync_receipts_device_event_pk' }),
  unique('sync_receipts_sale_id_unique').on(t.saleId),
]);

export const syncConflicts = pgTable('sync_conflicts', {
  id: uuid('id').primaryKey(),
  eventId: uuid('event_id').notNull(),
  saleId: uuid('sale_id').notNull().references(() => sales.id, { onDelete: 'restrict' }),
  kind: text('kind').notNull(),
  details: jsonb('details').notNull(),
  status: text('status').notNull(),
  createdAt: nowUtc(),
  resolvedAt: timestamp('resolved_at', { withTimezone: true }),
}, (t) => [
  index('sync_conflicts_status_created_idx').on(t.status, t.createdAt),
]);

export const auditLogs = pgTable('audit_logs', {
  id: uuid('id').primaryKey(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  actorId: uuid('actor_id').references(() => users.id, { onDelete: 'restrict' }),
  deviceId: uuid('device_id').references(() => devices.id, { onDelete: 'restrict' }),
  action: text('action').notNull(),
  entityType: text('entity_type').notNull(),
  entityId: uuid('entity_id').notNull(),
  metadata: jsonb('metadata').notNull(),
  createdAt: nowUtc(),
}, (t) => [
  index('audit_logs_store_created_idx').on(t.storeId, t.createdAt),
]);

export const catalogChangeLog = pgTable('catalog_change_log', {
  seq: bigint('seq', { mode: 'bigint' }).primaryKey().generatedAlwaysAsIdentity(),
  storeId: uuid('store_id').notNull().references(() => stores.id, { onDelete: 'restrict' }),
  entityType: text('entity_type').notNull(),
  entityId: uuid('entity_id').notNull(),
  op: text('op').notNull(),
  payload: jsonb('payload').notNull(),
  createdAt: nowUtc(),
}, (t) => [
  index('catalog_change_log_store_seq_idx').on(t.storeId, t.seq),
]);
